package main

import (
	"fmt"
	"strconv"
	"strings"
)

// TreeNode represents a node in a binary tree.
type TreeNode struct {
	Val   int
	Left  *TreeNode
	Right *TreeNode
}

// compress_string serializes a binary tree to a compact string and
// deserializes it back. The format uses space-separated values with
// "null" for nil nodes, produced via level-order (BFS) traversal.
//
// Example:     1
//             / \
//            2   3
//               / \
//              4   5
// Serializes to: "1 2 null null 3 4 5"

// Serialize converts a binary tree into a string representation.
func Serialize(root *TreeNode) string {
	if root == nil {
		return ""
	}

	var sb strings.Builder
	queue := []*TreeNode{root}

	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]

		if node == nil {
			sb.WriteString("null ")
		} else {
			sb.WriteString(fmt.Sprintf("%d ", node.Val))
			queue = append(queue, node.Left, node.Right)
		}
	}

	return strings.TrimSpace(sb.String())
}

// Deserialize converts a string representation back into a binary tree.
func Deserialize(data string) *TreeNode {
	data = strings.TrimSpace(data)
	if data == "" {
		return nil
	}

	parts := strings.Split(data, " ")
	if len(parts) == 0 {
		return nil
	}

	val, err := strconv.Atoi(parts[0])
	if err != nil {
		return nil
	}

	root := &TreeNode{Val: val}
	queue := []*TreeNode{root}
	i := 1

	for len(queue) > 0 && i < len(parts) {
		node := queue[0]
		queue = queue[1:]

		// Left child
		if i < len(parts) && parts[i] != "null" {
			leftVal, err := strconv.Atoi(parts[i])
			if err == nil {
				node.Left = &TreeNode{Val: leftVal}
				queue = append(queue, node.Left)
			}
		}
		i++

		// Right child
		if i < len(parts) && parts[i] != "null" {
			rightVal, err := strconv.Atoi(parts[i])
			if err == nil {
				node.Right = &TreeNode{Val: rightVal}
				queue = append(queue, node.Right)
			}
		}
		i++
	}

	return root
}

// compress_string is the main entry point: serializes then deserializes,
// returning the reconstructed tree. Useful as a round-trip identity check.
func compress_string(root *TreeNode) *TreeNode {
	return Deserialize(Serialize(root))
}

// TreeEqual checks structural and value equality of two binary trees.
func TreeEqual(a, b *TreeNode) bool {
	if a == nil && b == nil {
		return true
	}
	if a == nil || b == nil {
		return false
	}
	return a.Val == b.Val &&
		TreeEqual(a.Left, b.Left) &&
		TreeEqual(a.Right, b.Right)
}

package main

import (
	"strings"
	"testing"
)

func TestSerialize_NilTree(t *testing.T) {
	got := Serialize(nil)
	if got != "" {
		t.Errorf("Serialize(nil) = %q, want empty string", got)
	}
}

func TestSerialize_SingleNode(t *testing.T) {
	root := &TreeNode{Val: 42}
	got := Serialize(root)
	want := "42"
	if got != want {
		t.Errorf("Serialize = %q, want %q", got, want)
	}
}

func TestSerialize_LeftSkewed(t *testing.T) {
	//   1
	//  /
	// 2
	//  \
	//   3
	root := &TreeNode{Val: 1}
	root.Left = &TreeNode{Val: 2}
	root.Left.Right = &TreeNode{Val: 3}
	got := Serialize(root)
	want := "1 2 null null 3"
	if got != want {
		t.Errorf("Serialize = %q, want %q", got, want)
	}
}

func TestSerialize_Complete(t *testing.T) {
	//      1
	//     / \
	//    2   3
	//   / \ / \
	//  4  5 6  7
	root := &TreeNode{Val: 1}
	root.Left = &TreeNode{Val: 2}
	root.Right = &TreeNode{Val: 3}
	root.Left.Left = &TreeNode{Val: 4}
	root.Left.Right = &TreeNode{Val: 5}
	root.Right.Left = &TreeNode{Val: 6}
	root.Right.Right = &TreeNode{Val: 7}
	got := Serialize(root)
	want := "1 2 3 4 5 6 7"
	if got != want {
		t.Errorf("Serialize = %q, want %q", got, want)
	}
}

func TestSerialize_SparseTree(t *testing.T) {
	//      1
	//     / \
	//    2   3
	//         \
	//          5
	root := &TreeNode{Val: 1}
	root.Left = &TreeNode{Val: 2}
	root.Right = &TreeNode{Val: 3}
	root.Right.Right = &TreeNode{Val: 5}
	got := Serialize(root)
	want := "1 2 3 null null null 5"
	if got != want {
		t.Errorf("Serialize = %q, want %q", got, want)
	}
}

func TestSerialize_NegativeValues(t *testing.T) {
	root := &TreeNode{Val: -1}
	root.Left = &TreeNode{Val: -10}
	root.Right = &TreeNode{Val: 0}
	got := Serialize(root)
	want := "-1 -10 0"
	if got != want {
		t.Errorf("Serialize = %q, want %q", got, want)
	}
}

func TestDeserialize_EmptyString(t *testing.T) {
	got := Deserialize("")
	if got != nil {
		t.Errorf("Deserialize(\"\") = %v, want nil", got)
	}
}

func TestDeserialize_SingleValue(t *testing.T) {
	got := Deserialize("42")
	if got == nil || got.Val != 42 {
		t.Errorf("Deserialize(\"42\") = %v, want TreeNode{Val: 42}", got)
	}
	if got != nil && (got.Left != nil || got.Right != nil) {
		t.Error("single-node tree should have no children")
	}
}

func TestDeserialize_WithNulls(t *testing.T) {
	got := Deserialize("1 2 3 null null 4 5")
	if got == nil {
		t.Fatal("got nil root")
	}
	if got.Val != 1 {
		t.Errorf("root.Val = %d, want 1", got.Val)
	}
	if got.Left == nil || got.Left.Val != 2 {
		t.Errorf("left child = %v, want 2", got.Left)
	}
	if got.Right == nil || got.Right.Val != 3 {
		t.Errorf("right child = %v, want 3", got.Right)
	}
	if got.Left.Left != nil || got.Left.Right != nil {
		t.Error("node 2 should have no children")
	}
	if got.Right.Left == nil || got.Right.Left.Val != 4 {
		t.Errorf("node 3 left child = %v, want 4", got.Right.Left)
	}
	if got.Right.Right == nil || got.Right.Right.Val != 5 {
		t.Errorf("node 3 right child = %v, want 5", got.Right.Right)
	}
}

func TestRoundTrip_SingleNode(t *testing.T) {
	root := &TreeNode{Val: 1}
	got := compress_string(root)
	if !TreeEqual(root, got) {
		t.Error("round-trip failed for single node")
	}
}

