	root := &TreeNode{Val: 1}
	root.Left = &TreeNode{Val: 2}
	root.Right = &TreeNode{Val: 3}
	root.Left.Left = &TreeNode{Val: 4}
	root.Left.Right = &TreeNode{Val: 5}
	root.Right.Left = &TreeNode{Val: 6}
	root.Right.Right = &TreeNode{Val: 7}

	got := compress_string(root)
	if !TreeEqual(root, got) {
		t.Error("round-trip failed for complete tree")
	}
}

func TestRoundTrip_SparseTree(t *testing.T) {
	root := &TreeNode{Val: 10}
	root.Left = &TreeNode{Val: 20}
	root.Right = &TreeNode{Val: 30}
	root.Right.Left = &TreeNode{Val: 40}
	root.Right.Right = &TreeNode{Val: 50}
	root.Right.Left.Left = &TreeNode{Val: 60}

	got := compress_string(root)
	if !TreeEqual(root, got) {
