	}
}

func TestRoundTrip_NilTree(t *testing.T) {
	got := compress_string(nil)
	if got != nil {
		t.Error("round-trip of nil should return nil")
	}
}

func TestRoundTrip_LeftSkewed(t *testing.T) {
	root := &TreeNode{Val: 1}
	root.Left = &TreeNode{Val: 2}
	root.Left.Left = &TreeNode{Val: 3}
	root.Left.Left.Left = &TreeNode{Val: 4}

	got := compress_string(root)
	if !TreeEqual(root, got) {
		t.Error("round-trip failed for left-skewed tree")
	}
}

func TestRoundTrip_RightSkewed(t *testing.T) {
	root := &TreeNode{Val: 1}
	root.Right = &TreeNode{Val: 2}
	root.Right.Right = &TreeNode{Val: 3}
	root.Right.Right.Right = &TreeNode{Val: 4}

	got := compress_string(root)
	if !TreeEqual(root, got) {
