}

func TestRoundTrip_NegativeValues(t *testing.T) {
	root := &TreeNode{Val: -5}
	root.Left = &TreeNode{Val: -10}
	root.Right = &TreeNode{Val: 0}
	root.Left.Left = &TreeNode{Val: 100}

	got := compress_string(root)
	if !TreeEqual(root, got) {
		t.Error("round-trip failed for negative values")
	}
}

func TestRoundTrip_DeepTree(t *testing.T) {
	// Build a tree of depth 10 on the left side
	root := &TreeNode{Val: 0}
	cur := root
	for i := 1; i <= 10; i++ {
		cur.Left = &TreeNode{Val: i}
		cur = cur.Left
	}

	got := compress_string(root)
	if !TreeEqual(root, got) {
		t.Error("round-trip failed for deep tree")
	}
}

func TestTreeEqual_BothNil(t *testing.T) {
	if !TreeEqual(nil, nil) {
		t.Error("nil == nil should be true")
	}
}

func TestTreeEqual_OneNil(t *testing.T) {
	root := &TreeNode{Val: 1}
	if TreeEqual(root, nil) {
		t.Error("non-nil != nil should be false")
	}
	if TreeEqual(nil, root) {
		t.Error("nil != non-nil should be false")
	}
}

func TestTreeEqual_DifferentStructure(t *testing.T) {
	a := &TreeNode{Val: 1}
	a.Left = &TreeNode{Val: 2}

	b := &TreeNode{Val: 1}
	b.Right = &TreeNode{Val: 2}

	if TreeEqual(a, b) {
		t.Error("different structures should not be equal")
	}
}

func TestTreeEqual_DifferentValues(t *testing.T) {
	a := &TreeNode{Val: 1}
	b := &TreeNode{Val: 2}
	if TreeEqual(a, b) {
		t.Error("different values should not be equal")
	}
}

func TestSerialize_LeadingTrailingSpaces(t *testing.T) {
	root := &TreeNode{Val: 1}
	root.Left = &TreeNode{Val: 2}
	s := Serialize(root)
	if strings.HasPrefix(s, " ") || strings.HasSuffix(s, " ") {
		t.Errorf("Serialize output has leading/trailing spaces: %q", s)
	}
}

func TestDeserialize_WithExtraSpaces(t *testing.T) {
	got := Deserialize("  1  2  3  ")
	if got == nil || got.Val != 1 {
		t.Errorf("Deserialize with extra spaces failed: got %v", got)
	}
}

func TestRoundTrip_OnlyRightChildren(t *testing.T) {
	root := &TreeNode{Val: 100}
	root.Right = &TreeNode{Val: 200}
	root.Right.Right = &TreeNode{Val: 300}

	got := compress_string(root)
	if !TreeEqual(root, got) {
		t.Error("round-trip failed for right-only tree")
	}
}

func TestRoundTrip_WideTree(t *testing.T) {
	//      1
	//     /|\
	//    2 3 4  (not binary, but test many nodes at same level)
	// Actually keep it binary:
	//        1
	//       / \
	//      2   3
	//     / \   \
	//    4   5   6
	root := &TreeNode{Val: 1}
	root.Left = &TreeNode{Val: 2}
	root.Right = &TreeNode{Val: 3}
	root.Left.Left = &TreeNode{Val: 4}
	root.Left.Right = &TreeNode{Val: 5}
	root.Right.Right = &TreeNode{Val: 6}

	got := compress_string(root)
	if !TreeEqual(root, got) {
		t.Error("round-trip failed for wide tree")
	}
